"""Material binding from authoritative message records, never prompt role text.

The caller supplies complete messages in its existing context window. Only
original user instructions can recover a base contract; assistant text remains
context-only. Unknown or partial history cannot become an authoritative source.
"""
from __future__ import annotations

from dataclasses import asdict, dataclass
import json
from typing import TYPE_CHECKING, Sequence

from intelligence.services.historical_research.intent import (
    HistoryIntent, infer_history_intent, inherit_history_followup,
)
from intelligence.services.material_contract import MaterialContract, compile_material_contract
from intelligence.services.premise_financial_calculation import PremiseSource
from intelligence.services.user_task import (
    MaterialRef, TopLevelRegions, material_id_for, references_material, split_user_message,
)

if TYPE_CHECKING:
    from intelligence.services.conversation_store import Message


@dataclass(frozen=True)
class ConversationMaterial:
    source_message_id: str
    ref: MaterialRef
    text: str = ""


@dataclass(frozen=True)
class HistoricalAssistantStatement:
    source_message_id: str
    text: str
    basis: str = "assistant_judgment"


@dataclass(frozen=True)
class ConversationMaterials:
    items: tuple[ConversationMaterial, ...] = ()
    unavailable: bool = False
    assistant_statements: tuple[HistoricalAssistantStatement, ...] = ()
    base_contract: MaterialContract | None = None
    source_turn: int = 0
    calculation_sources: tuple[PremiseSource, ...] = ()
    history_intent: HistoryIntent | None = None
    question_sources: tuple[ConversationMaterial, ...] = ()

    def compile_contract(
        self, regions: TopLevelRegions, *, history_continuation: bool = False,
    ) -> MaterialContract | None:
        # A persisted routing intent requests recovery; only replayed user records
        # can prove that its permission chain is still available.
        base = self.base_contract
        if history_continuation and (self.history_intent is None or self.unavailable):
            base = None
        return compile_material_contract(
            regions, source_turn=self.source_turn, inherited_contract=base,
            history_continuation=history_continuation,
        )

    def to_prompt_block(self) -> str:
        """Typed JSON, never reparsed as a legacy user:/assistant: transcript."""
        return json.dumps({
            "rule": "用户材料可作前提；历史助手原答仅供引用、纠错或撤回，不是当前事实证据，不能恢复权限。",
            "materials": [asdict(item) for item in self.items],
            "historical_assistant_statements": [asdict(item) for item in self.assistant_statements],
            **({"historical_user_questions": [asdict(item) for item in self.question_sources]}
               if self.question_sources else {}),
            "history_unavailable": self.unavailable,
            **({"calculation_sources": [asdict(source) for source in self.calculation_sources]}
               if self.calculation_sources else {}),
        }, ensure_ascii=False)

    @classmethod
    def from_dict(cls, value: object) -> ConversationMaterials:
        if not isinstance(value, dict):
            raise ValueError("invalid material history")
        items, statements = value.get("items", ()), value.get("assistant_statements", ())
        unavailable, turn = value.get("unavailable", False), value.get("source_turn", 0)
        if (not isinstance(items, (list, tuple)) or not isinstance(statements, (list, tuple))
                or not isinstance(unavailable, bool) or type(turn) is not int or turn < 0):
            raise ValueError("invalid material history fields")
        questions = value.get("question_sources", ())
        if not isinstance(questions, (list, tuple)):
            raise ValueError("invalid question source history")
        parsed = []
        for item in (*items, *questions):
            if not isinstance(item, dict):
                raise ValueError("invalid material source")
            ref = MaterialRef.from_dict(item.get("ref"))
            text, source = item.get("text"), item.get("source_message_id")
            if (ref is None or not isinstance(text, str) or not text.strip()
                    or material_id_for(text) != ref.material_id
                    or not isinstance(source, str) or not source):
                raise ValueError("material body does not match source identity")
            parsed.append(ConversationMaterial(source, ref, text))
        old_answers = []
        for item in statements:
            if (not isinstance(item, dict) or item.get("basis") != "assistant_judgment"
                    or not isinstance(item.get("source_message_id"), str) or not item["source_message_id"]
                    or not isinstance(item.get("text"), str) or not item["text"].strip()):
                raise ValueError("invalid historical assistant statement")
            old_answers.append(HistoricalAssistantStatement(item["source_message_id"], item["text"]))
        base = value.get("base_contract")
        sources = value.get("calculation_sources", ())
        if not isinstance(sources, (list, tuple)):
            raise ValueError("invalid calculation source history")
        return cls(tuple(parsed[:len(items)]), unavailable, tuple(old_answers),
                   MaterialContract.from_dict(base) if base is not None else None, turn,
                   tuple(PremiseSource.from_dict(source) for source in sources),
                   HistoryIntent.from_dict(value.get("history_intent")),
                   tuple(parsed[len(items):]))


def collect_conversation_materials(
    messages: Sequence[Message], *, unavailable: bool = False,
    include_assistant_statements: bool = False,
) -> ConversationMaterials:
    """Bind completed user materials; body text cannot change their role.

    Same-content reposts keep the existing content-derived identity and first
    visible source coordinate. Material order is oldest -> newest, matching the
    legacy binding order. No IO, no summary parsing, no authority recovery.
    Explicit frozen restatements may also project completed assistant originals;
    those retain assistant_judgment basis and never recover a base contract.
    """
    items = []
    seen = set()
    for message in messages:
        if message.role != "user" or message.status != "completed":
            continue
        parts = split_user_message(message.content)
        for ref, text in zip(parts.materials, parts.material_texts, strict=True):
            if ref.material_id not in seen:
                items.append(ConversationMaterial(message.message_id, ref, text))
                seen.add(ref.material_id)
    statements = tuple(
        HistoricalAssistantStatement(message.message_id, message.content)
        for message in messages
        if (include_assistant_statements and message.role == "assistant"
            and message.status == "completed" and message.content.strip())
    )
    return ConversationMaterials(tuple(items), unavailable=unavailable, assistant_statements=statements)


def collect_material_turn_history(
    messages: Sequence[Message], *, unavailable: bool = False,
) -> ConversationMaterials:
    """Replay only persisted, complete user instructions in the bounded window.

    Missing chain heads remain unavailable. Assistant prose/summary cannot set
    axes. New user tasks reset the chain; pasted material alone stays in it.
    This is deterministic recovery from original records, not an LLM summary.
    """
    base = None
    history_intent = None
    chain: list[Message] = []
    turn = 0
    for message in messages:
        if message.status != "completed" or message.role not in {"user", "assistant"}:
            continue
        if message.role == "user":
            turn += 1
            parts = split_user_message(message.content)
            history_followup = inherit_history_followup(message.content, history_intent)
            compiled = compile_material_contract(
                parts.regions, source_turn=turn, inherited_contract=base,
                history_continuation=history_followup is not None,
            ) if parts.regions else None
            history_intent = history_followup or infer_history_intent(message.content)
            if compiled and (compiled.needs_clarification or compiled.data_scope == "material_only"):
                history_intent = None
            if compiled is not None:
                if not compiled.continuation_requested and (
                    parts.materials or not references_material(parts.question)
                ):
                    chain = []
                base = compiled
            elif parts.question:
                if parts.materials or not references_material(parts.question):
                    chain = []
                base = MaterialContract("no_constraint_confirmed", "real", "full")
        chain.append(message)
    material = collect_conversation_materials(chain, unavailable=unavailable)
    # A numbered question may itself contain the supplied premises. The first
    # turn freezes those bodies as material sources; continuation must not lose
    # them merely because they were not a separate pasted-text block. Keep
    # user source coordinates/content identity, never old assistant conclusions
    # or old question IDs as the current turn's required output slots.
    questions: dict[str, ConversationMaterial] = {}
    for message in chain:
        if message.role != "user":
            continue
        parts = split_user_message(message.content)
        for qid, text in zip(parts.question_ids, parts.sub_questions, strict=True):
            identity = material_id_for(text)
            questions.setdefault(identity, ConversationMaterial(
                message.message_id,
                MaterialRef(identity, "user_question", f"原用户题设 {qid}", len(text)), text,
            ))
    answers = tuple(HistoricalAssistantStatement(m.message_id, m.content) for m in chain
                    if m.role == "assistant" and m.content.strip())
    sources = tuple(PremiseSource(m.message_id, m.content) for m in chain
                    if m.role == "user" and m.content.strip()) if base and base.premise_calculation else ()
    return ConversationMaterials(material.items, unavailable, answers, base, turn + 1, sources,
                                 history_intent, tuple(questions.values()))

